"""Bounded checks for the scoped cyclic/phase-plane Life obstruction."""
from math import gcd
from pathlib import Path
import json


def life(cells, p):
    out = set()
    for x in range(p):
        for y in range(p):
            count = sum(((x+dx) % p, (y+dy) % p) in cells
                        for dx in (-1, 0, 1) for dy in (-1, 0, 1)
                        if (dx, dy) != (0, 0))
            if count == 3 or (count == 2 and (x, y) in cells):
                out.add((x, y))
    return out


def normalize(x, y, m, s, n):
    # Period lattice generated by (m,0),(s,n).
    k, yy = divmod(y, n)
    return ((x-k*s) % m, yy)


def cycles(m, s, n, gx, gy):
    unseen = {(x, y) for x in range(m) for y in range(n)}
    count = 0
    while unseen:
        start = min(unseen)
        point = start
        count += 1
        while point in unseen:
            unseen.remove(point)
            point = normalize(point[0]+gx, point[1]+gy, m, s, n)
        assert point == start
    return count


def verify():
    still_lifes = period_tests = dead_cell_tests = 0
    for p in range(5, 26):
        cells = {(0, 0), (0, 1), (1, 0), (1, 1)}
        assert life(cells, p) == cells
        still_lifes += 1
        for x in range(p):
            for y in range(p):
                if (x, y) not in cells:
                    count = sum(((x+dx) % p, (y+dy) % p) in cells
                                for dx in (-1, 0, 1)
                                for dy in (-1, 0, 1)
                                if (dx, dy) != (0, 0))
                    assert count <= 2
                    dead_cell_tests += 1
        for a in range(p):
            for b in range(p):
                shifted = {((x+a) % p, (y+b) % p) for x, y in cells}
                assert (shifted == cells) == ((a, b) == (0, 0))
                period_tests += 1

    skew_tori = generators = sharp_examples = descent_tests = 0
    for p in range(2, 8):
        for mu in range(1, 4):
            for nu in range(1, 4):
                m, n = p*mu, p*nu
                for s in range(0, m, p):
                    skew_tori += 1
                    best = m*n
                    for gx in range(m):
                        for gy in range(n):
                            actual = cycles(m, s, n, gx, gy)
                            # Index of the lattice generated by both
                            # periods and the proposed generator.
                            index = gcd(m*n, gcd(m*gy, s*gy-n*gx))
                            assert actual == index and actual >= p
                            best = min(best, actual)
                            generators += 1
                            # Reduction mod p descends through both
                            # skew identifications, including negatives.
                            for x, y in ((gx, gy), (gx+m, gy),
                                         (gx+s, gy+n), (gx-s, gy-n)):
                                xx, yy = normalize(x, y, m, s, n)
                                assert (xx % p, yy % p) == (gx % p, gy % p)
                                descent_tests += 1
                    assert best == gcd(m, gcd(s, n))
                    if mu == nu == 1 and s == 0:
                        assert best == p
                        sharp_examples += 1

    consecutive_tori = crt_cells = neighbor_tests = 0
    for m in range(1, 25):
        length = m*(m+1)
        encode = lambda x, y: (m*x+(m+1)*y) % length
        seen = {encode(x, y) for x in range(m+1) for y in range(m)}
        assert seen == set(range(length))
        consecutive_tori += 1
        crt_cells += length
        for x in range(m+1):
            for y in range(m):
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        if (dx, dy) != (0, 0):
                            assert encode((x+dx) % (m+1), (y+dy) % m) == (
                                encode(x, y)+m*dx+(m+1)*dy) % length
                            neighbor_tests += 1

    arbitrary_cyclic_quotients = lift_checks = 0
    for length in range(1, 33):
        for m in range(1, 17):
            encode = lambda x, y: (m*x+(m+1)*y) % length
            assert {encode(-k, k) for k in range(length)} == set(range(length))
            arbitrary_cyclic_quotients += 1
            # Check arbitrary-length soundness independently of the
            # consecutive-rectangle isomorphism used for completeness.
            for k in range(length):
                x, y = -k, k
                assert encode(x+length, y) == k
                assert encode(x, y+length) == k
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        assert encode(x+dx, y+dy) == (
                            k+m*dx+(m+1)*dy) % length
                        lift_checks += 1

    stride_divisor_tests = accepted_strides = 0
    for length in range(1, 25):
        q = 512**length
        for exponent in range(9*length+1):
            W = 2**exponent
            accepted = W > 1 and (W-1) % 511 == 0
            assert q % W == 0
            assert accepted == (exponent > 0 and exponent % 9 == 0)
            stride_divisor_tests += 1
            accepted_strides += accepted

    return {
        'status': 'PASS',
        'review': 'Author and independent complete scoped proof/source review pass; fresh read-only verification exactly matches the saved receipt.',
        'scope': 'Regular translation quotients with a commuting cyclic shift; no general encoding lower bound.',
        'still_life_targets': still_lifes,
        'exact_period_tests': period_tests,
        'dead_cell_neighbor_bounds': dead_cell_tests,
        'compatible_skew_tori': skew_tori,
        'cyclic_generator_tests': generators,
        'quotient_descent_tests': descent_tests,
        'sharp_phase_examples': sharp_examples,
        'consecutive_dimension_tori': consecutive_tori,
        'consecutive_dimension_cells': crt_cells,
        'consecutive_neighbor_checks': neighbor_tests,
        'arbitrary_cyclic_quotients': arbitrary_cyclic_quotients,
        'arbitrary_cyclic_lift_checks': lift_checks,
        'stride_divisor_tests': stride_divisor_tests,
        'accepted_stride_examples': accepted_strides,
        'conditional_stride_geometry_operations': 3,
        'certificate_operations': None,
        'coprime_padding_universality_established': False,
    }


if __name__ == '__main__':
    result = verify()
    Path(__file__).with_suffix('.json').write_text(
        json.dumps(result, indent=2)+'\n', encoding='utf-8')
    print(json.dumps(result, indent=2))
